//! The surface Swift sees, generated by UniFFI.

use std::sync::Arc;

use crate::ApduTransport;

#[derive(Debug, thiserror::Error, uniffi::Error)]
pub enum ConnectionError {
    #[error("{message}")]
    Failed { message: String },
}

impl From<uniffi::UnexpectedUniFFICallbackError> for ConnectionError {
    fn from(e: uniffi::UnexpectedUniFFICallbackError) -> Self {
        Self::Failed { message: e.reason }
    }
}

/// Implemented in Swift on top of the USB-C smart card connection.
#[uniffi::export(with_foreign)]
pub trait CardConnection: Send + Sync {
    /// Sends one command APDU and returns the response with its status bytes.
    fn transmit(&self, apdu: Vec<u8>) -> Result<Vec<u8>, ConnectionError>;
    /// Called just before the key starts waiting for a touch.
    fn touch_needed(&self);
}

struct Adapter(Arc<dyn CardConnection>);

impl ApduTransport for Adapter {
    fn transmit(&self, apdu: &[u8]) -> Result<Vec<u8>, String> {
        self.0.transmit(apdu.to_vec()).map_err(|e| e.to_string())
    }
}

/// Whether an error's message (from any of paw's error types) says the
/// store was busy: another part of paw, or the AutoFill extension, was
/// using it for longer than paw waits. Nothing was changed, the store is
/// not broken, and trying again will work. Its message starts with "the
/// password store is busy".
#[uniffi::export]
pub fn is_store_busy(message: String) -> bool {
    crate::lock::is_store_busy(&message)
}

